def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def check_condition(n):
    if n == 1:
        return False # Sum is empty, usually taken as 0. 0 != 1.

    factors = prime_factorization(n)
    sum_ratio = 0
    for p, e in factors.items():
        sum_ratio += e / p

    # Check if the sum is numerically close to 1.0
    return abs(sum_ratio - 1.0) < 1e-9

# List of composite numbers n in [1, 40] not explicitly verified in W1 (n=4, 6, 8, 9, 10, 12)
unverified_composites = [14, 15, 16, 18, 20, 21, 22, 24, 25, 26, 28, 30, 32, 33, 34, 35, 36, 38, 39, 40]

results = {}
for n in unverified_composites:
    is_solution = check_condition(n)
    results[n] = is_solution

print("Verification of unverified composite numbers (1 <= n <= 40):")
for n, solution in results.items():
    print(f"n={n}: Solution? {solution}")

